import openpyxl
src='/mnt/hhq/data/MiMotable/阅读记录表1.xlsx'
filled='/tmp/llm_rollout_bnmage3p/阅读记录表1_template_7397_input_filled.xlsx'
tpl='/tmp/llm_rollout_bnmage3p/阅读记录表1_template_7397_input.xlsx'

def get(p):
    wb=openpyxl.load_workbook(p, data_only=False)
    ws=wb['阅读记录表']
    d={}
    for r in range(2,21):
        for c in range(2,12):
            cell=ws.cell(row=r,column=c)
            d[(r,c)]=(cell.value, cell.number_format)
    return d, ws.merged_cells.ranges

s, sm = get(src)
f, fm = get(filled)
t, tm = get(tpl)

# compare values where source non-None
mismatch=[]
for k in s:
    if s[k][0] is not None:
        if f[k][0] != s[k][0]:
            mismatch.append((k, s[k][0], f[k][0]))
print('value mismatches vs source (non-none):', len(mismatch))
for m in mismatch: print(m)

# compare number formats in template vs filled (should be same)
fmt_changed=[]
for k in t:
    if t[k][1] != f[k][1]:
        fmt_changed.append((k,t[k][1],f[k][1]))
print('format changed vs template:', len(fmt_changed))
for m in fmt_changed[:20]: print(m)

# formulas count
formulas=[]
for k in f:
    v=f[k][0]
    if isinstance(v,str) and v.startswith('='):
        formulas.append((k,v))
print('formulas in filled:', len(formulas))
for m in formulas: print(m)

print('merged filled:', fm)
print('merged source:', sm)
